  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_request_method, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name IN ('ts-auth-service','ts-verification-code-service') AND (span_name IN ('GET','PUT /error') OR span_name LIKE 'PUT%') GROUP BY ALL",
          "claim": "Auth's outgoing GET calls get 405 from verification-code; verification-code sees 2118 PUT /error requests, so method/path is rewritten in flight."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "Auth login spans fail with HTTP 500 in 2118 cases, versus no errors in the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "Dashboard login requests fail with 500 (120 spans, p50 about 3.7 s) because the auth call fails."
        }
      ]
    }
  ]
}
